'use client';

/* SegmentedNav — 分段切换导航（seg 规范的独立组件化）
 * 容器 m12 + padding 4 + surface 底 + 边框；段高 control-sm 32、radius-s 8
 * 三态：hover=轻底+提亮 / 选中=active 实底+主文字+600（选中不吃 hover）/ 按下缩放
 * displayMode：both 文字+图标 / text 仅文字 / icon 仅图标（段变 32 方格） */
import NamedIcon from '../../components/NamedIcon';
import './SegmentedNav.css';

export interface SegmentedOption {
  label?: string;
  icon?: string;
  value: string;
}

export interface SegmentedNavProps {
  options?: SegmentedOption[];
  value?: string;
  onChange?: (value: string) => void;
  /** both=文字+图标 / text=仅文字 / icon=仅图标 */
  displayMode?: 'both' | 'text' | 'icon';
  ariaLabel?: string;
}

export default function SegmentedNav({
  options = [],
  value = '',
  onChange,
  displayMode = 'both',
  ariaLabel
}: SegmentedNavProps) {
  return (
    <div className="sn-group" role="tablist" aria-label={ariaLabel}>
      {options.map(opt => {
        const active = opt.value === value;
        const iconOnly = displayMode === 'icon';
        return (
          <button
            key={opt.value}
            type="button"
            role="tab"
            aria-selected={active}
            className={`sn-btn${iconOnly ? ' sn-btn--icon' : ''}`}
            data-active={active}
            onClick={() => onChange?.(opt.value)}
            title={iconOnly ? opt.label : undefined}
          >
            {displayMode !== 'text' && opt.icon ? <NamedIcon name={opt.icon} em={1.25} /> : null}
            {displayMode !== 'icon' && opt.label ? <span>{opt.label}</span> : null}
          </button>
        );
      })}
    </div>
  );
}

/* SegmentedNav — seg 规范独立化（sn- 前缀命名空间）
   三态：hover 轻底+提亮 / 选中 active 实底+600（选中不吃 hover）/ 按下缩放 */
.sn-group {
  display: inline-flex;
  gap: var(--space-1);
  background: var(--color-bg-surface);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-m);
  padding: var(--space-1);
}

.sn-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-s);
  height: var(--control-sm);
  padding: 0 var(--space-m);
  border: none;
  border-radius: var(--radius-s);
  background: transparent;
  color: var(--color-text-muted);
  font-size: var(--text-sm);
  font-weight: 400;
  cursor: pointer;
  transition: background-color var(--transition-fast), color var(--transition-fast), transform var(--transition-fast);
}

.sn-btn:active {
  transform: scale(0.96);
}

.sn-btn:hover:not([data-active='true']) {
  background: var(--color-hover-overlay);
  color: var(--color-text-secondary);
}

.sn-btn[data-active='true'] {
  background: color-mix(in srgb, #ffffff 5%, var(--color-bg-active)); /* 实底+叠亮底 */
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
  color: var(--color-text-primary);
  font-weight: 600;
}

/* 仅图标模式：32 方格 */
.sn-btn--icon {
  width: var(--control-sm);
  padding: 0;
}
